import subprocess,sys,time,json,gzip,base64,zipfile,hashlib
from pathlib import Path
from IPython.display import display,HTML
A=Path('/kaggle/working/rascar_v16')
for name,source in json.loads(gzip.decompress(base64.b64decode(''))).items():(A/name).write_text(source)

