workers16={}
for name,script in [('dino16','build_dino_features.py'),('pose16','extract_multiview_pose.py')]:
 workers16[name]=subprocess.Popen([sys.executable,'-u',str(A/script)],cwd=A,stdout=open(A/f'{name}.log','w'),stderr=subprocess.STDOUT)
while any(p.poll() is None for p in workers16.values()):
 print('V16_PROGRESS',{k:p.poll() for k,p in workers16.items()},[(k,(A/f'{k}.log').read_text()[-180:]) for k in workers16],flush=True)
 time.sleep(30)
